function cookie(e){let t=document,o=()=>{let o=decodeURIComponent(t.cookie).split(";");for(let t in o){let i=o[t].trim().split("=");if(i[0]===e)return i.slice(1).join("=")}},i=(o,i=NaN)=>t.cookie=e+"="+o+";path=/"+(isNaN(i)?"":";expires="+new Date(Date.now()+1e3*i).toUTCString());return{value:o,set:i,delete:()=>i("",0),toString:o}}